"""Reconcile the 16 pending adapters against production read-only scope."""
import json
from pathlib import Path
base=Path(__file__).parent
previous=json.loads((base/'implementation.json').read_text())
# id, class, priority, observation, missing adapter, honest result boundary, source evidence
rows=[
('MB-0010','STATE_OR_METADATA','P1','Read effective Admin route, gateway/WAF/access policy and its binding to the actual origin and ingress paths.','Gateway/provider reader plus policy evaluator covering alternate origins, proxies and IPv4/IPv6. Optional approved GET probes supplement policy; a denied-source vantage must actually exist.','PASS only the enumerated ingress policy. A 403/404 from one source does not establish restricted Admin access. GET may produce logs/session state; strict zero-write deployments must use configuration observation only.','src/Engine/Checks/ProductionRuntimeCheck.php'),
('MB-0733','STATIC_SEMANTICS','P2','Parse deployed PHP/PHTML output sinks in HTML text, attributes and URLs.','Context-aware PHP/HTML parser, dataflow and installed escaper/trusted-fragment contracts; complete custom template inventory.','PASS only proven supported sinks. Dynamic templates, plugins and unresolved values remain UNKNOWN; no general XSS-free claim.','src/Engine/Checks/AutomatedSourcePolicyCheck.php'),
('MB-0736','STATIC_SEMANTICS','P2','Parse deployed PHP-generated JavaScript, HTML script contexts and serializers.','Nested PHP/HTML/JS parser and version-bound serializer/escaping semantics.','PASS only supported contexts whose values and encoding can be proved; escaping method-name presence is insufficient.','src/Engine/Checks/AutomatedSourcePolicyCheck.php'),
('MB-0094','STATIC_SEMANTICS','P1','Read enabled routes, webapi.xml, ACL declarations, DI/plugins/preferences and actual role/resource grants.','Complete route-to-effective-handler resolver and control-flow proof that supported routes enforce the required resource before protected reads/actions.','Declared ACL and stored grants can be verified separately. Full function-level authorization remains UNKNOWN for unsupported dispatch, plugins or business ownership. Do not execute production bootstrap/controller code to resolve it.','src/Engine/Checks/AdminAclCheck.php'),
('MB-0099','STATIC_SEMANTICS','P1','Read download/export routes, handler code and object ownership/access checks before protected content is returned.','Route resolver and source dataflow/control-flow proof from caller identity and object ID to ownership guard and output sink.','A protected-route declaration is a narrow predicate, not proof of object-level authorization. Do not download real customer documents as a scan probe.','src/Engine/Checks/Families/AuthorizationSourceChecks.php'),
('MB-0043','STATE_OR_METADATA','P1','Read actual logging sinks, installed rotation/retention rules, timer/cron activation and recent execution status.','Host logrotate/systemd, container runtime and managed logging adapters with complete sink mapping and bounded read permissions.','Verify installed policy and observed execution timestamps, not future success or every historical rotation. Never run logrotate, restart services or force rotation.','src/Engine/Checks/CronCheck.php'),
('MB-0051','STATE_OR_METADATA','P2','Read deployed package graph, advisory constraints and available fixed releases.','Read-only dependency constraint solver with correct platform/lock/repository inputs; no Composer plugins/scripts. Alternative mitigations need independently observable predicates.','Prove a compatible candidate under collected constraints, not successful application upgrade, behavioral compatibility or efficacy of a declared mitigation. Fresh narrower ID needed.','src/Engine/Checks/Families/ComposerAdvisoryChecks.php'),
('MB-0052','STATE_OR_METADATA','P2','Read enabled Magento module configuration and map deployed modules to exact package versions and authoritative maintenance status.','Complete module/package mapping including app/code modules, bounded module.xml/registration parsing and explicit high-risk policy plus fresh maintenance provider.','High-risk is a technical policy input, not a fact inferred from names. No vendor data or unmatched enabled module => UNKNOWN.','src/Engine/Checks/Families/ComposerRepositoryChecks.php'),
('MB-0054','STATE_OR_METADATA','P1','Match production package/advisory CVE identities against a dated complete KEV feed.','Authoritative feed provenance/freshness, CVE alias resolution and complete advisory-to-installed-version mapping; technical remediation priority/SLA if priority is assessed.','A verified KEV match is actionable. Absence is meaningful only within complete mapped advisory coverage; a generic known_exploited flag is insufficient. Prioritization is distinct from absence of KEV.','src/Engine/Checks/Families/ComposerAdvisoryChecks.php'),
('MB-0058','STATE_OR_METADATA','P2','Compare installed extension identities/versions with releases compatible with the deployed Magento/PHP versions.','Marketplace/vendor read-only release provider, identity mapping, compatibility and lifecycle metadata with explicit freshness.','Latest version is not automatically safest/compatible. Unsupported private vendors or missing compatibility data remain UNKNOWN.','src/Engine/Checks/Families/ComposerRepositoryChecks.php'),
('MB-0060','STATE_OR_METADATA','P2','Read vendor lifecycle and, where available, entitlement status for the exact deployed extension/version.','Actual vendor/account read-only API; exact product/account/version binding, expiry and freshness.','No universal support API is assumed. If the vendor exposes no machine-verifiable status, this provider remains unsupported; no assertion file substitutes for vendor status.','src/Engine/Checks/Families/ComposerRepositoryChecks.php'),
('MB-0075','STATIC_SEMANTICS','P1','Read deployed provider module/version, effective webhook configuration and handler paths through SDK verification to protected actions.','Stripe/Adyen/current-PayPal adapters plus control-flow and dataflow proof of raw-body/header/endpoint-secret binding, rejection handling and supported replay controls.','Read-only can prove supported code/config predicates without submitting events. Existing negative diagnostics do not prove enforcement or replay prevention; unresolved paths remain UNKNOWN.','src/Engine/Checks/ProviderWebhookSourceCheck.php'),
('MB-0076','STATE_OR_METADATA','P1','Read complete effective egress rules for the actual application network namespace, CNI/security group and gateways, including IPv4/IPv6 and exceptions.','Namespace-bound nftables/iptables/CNI/cloud policy readers and rule-order evaluator matched to a technical destination policy.','Default DROP alone is insufficient. Do not change firewall rules, use credentialed egress probes or infer every possible network path from one namespace.','src/Engine/Checks/SystemCheck.php'),
('MB-0078','STATE_OR_METADATA','P1','Read effective gateway TLS configuration/provider policy; optionally perform bounded TLS handshakes to declared production endpoints/SNI.','Gateway/provider adapter plus TLS1.2/1.3 cipher enumerator with recorded client capabilities, coverage and correct ingress binding.','One negotiated strong cipher is insufficient. Handshakes are active non-business-mutating probes, not passive reads; require rate bounds and explicit probe mode. Missing enumeration capability => UNKNOWN.','src/Engine/Checks/WebServerConfigCheck.php'),
('MB-0079','STATE_OR_METADATA','P1','Resolve declared credentials from effective Magento configuration to environment/file/secret-manager/database provenance without reporting values.','Version-bound sensitive config paths, precedence and secret-store metadata adapters; actual credential inventory and narrowly scoped read access.','Rewrite env.php-only requirement: assess protected approved storage/provenance, not a universal ban on encrypted DB or managed secrets. Do not export raw keys or bootstrap arbitrary project PHP.','src/Engine/Checks/Families/DataProtectionSourceChecks.php'),
('MB-0081','STATE_OR_METADATA','P1','Read active integration identities, effective resource grants, token status and actual ingress/egress policies.','Integration-to-ACL/network resolver with explicit expected resource/destination policy; provider metadata reader where relevant.','Compare observed grants to a technical allow-list. This does not establish business necessity; masked token metadata is enough, token material must not be retained.','src/Engine/Checks/AdminAclCheck.php'),
]
index={r['backlog_id']:r for r in previous['requirements'] if r['disposition']=='ADAPTER_PENDING'}
assert len(rows)==16 and {r[0] for r in rows}==set(index), 'Review must cover every pending adapter exactly once'
result=[]
for rid,kind,priority,observe,missing,boundary,source in rows:
    assert Path(source).is_file(), source
    result.append(dict(backlog_id=rid,title=index[rid]['original_title'],category=kind,priority=priority,production_readonly_candidate=True,implemented_by_this_review=False,original_criterion_verified=False,production_observation=observe,missing_adapter=missing,result_boundary=boundary,repository_evidence=source))
out=dict(date='2026-10-18',scope='All 16 ADAPTER_PENDING requirements, production read-only first; repository review only, no production access',counts=dict(state_or_metadata=11,static_semantics=5,implemented_by_this_review=0),contract=dict(no_production_business_writes=True,no_human_evidence=True,unknown_on_incomplete_observation=True,no_original_ids_reactivated=True),requirements=result)
(base/'production-readonly-review.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
print('Validated 16 exact pending IDs: 11 state/metadata candidates; 5 static-semantics candidates; zero implemented/verified claims.')
